SELECT DISTINCTROW tblEingabeUnGruppe.Gruppe, tblEingabeUnGruppe.Datum, tblEingabeUnGruppe.Zeit, Gruppenmerkmale.Anodencoating, Gruppenmerkmale.Kathodencoating, Gruppenmerkmale.Membrantyp, Gruppenmerkmale.Elektrodenabstand, tblEingabeUnGruppe.[I Gesamt], ([tblEingabeUnGruppe]![I Gesamt]/GetGewFlaeche()) AS i, tblEingabeUnGruppe.Cc, tblEingabeUnGruppe.[t An], tblEingabeUnGruppe.[t Ka], ([tblEingabeUnGruppe]![t An]+[tblEingabeUnGruppe]![t Ka])/2 AS tm, tblEingabeUnGruppe.[U Gesamt], tblEingabeUnGruppe.n, [U Gesamt]/[n] AS Ui, UnBer([Ui],[i],[tm],[Cc]) AS Un, GetGewiRef() AS iRef
FROM tblGewDaten, tblEingabeUnGruppe INNER JOIN Gruppenmerkmale ON tblEingabeUnGruppe.Gruppe = Gruppenmerkmale.Gruppe
WHERE (((tblEingabeUnGruppe.Datum)>=[tblGewDaten].[Anfangsdatum] And (tblEingabeUnGruppe.Datum)<=[tblGewDaten].[Enddatum]) AND ((tblEingabeUnGruppe.[I Gesamt]) Is Not Null) AND ((tblEingabeUnGruppe.Cc) Is Not Null) AND ((tblEingabeUnGruppe.[t An]) Is Not Null) AND ((tblEingabeUnGruppe.[t Ka]) Is Not Null) AND ((tblEingabeUnGruppe.[U Gesamt]) Is Not Null) AND ((tblEingabeUnGruppe.n) Is Not Null))
ORDER BY tblEingabeUnGruppe.Gruppe, tblEingabeUnGruppe.Datum, tblEingabeUnGruppe.Zeit;
